import json

ALLOWED_FIELDS = {
    "description", "actual_behavior", "expected_behavior", "affected_user_id",
    "occurred_at", "error_messages", "steps_to_reproduce", "environment",
    "reported_feature_name"
}
SCENARIOS = {
    "creation_failed", "result_missing", "incorrect_result",
    "visibility_problem", "retry_problem", "other", "unknown"
}
STATES = {"not_created", "created", "unknown"}


def strings(value, label):
    if not isinstance(value, list) or any(
        not isinstance(entry, str) or not entry.strip() for entry in value
    ):
        raise ValueError(f"{label} must be an array of nonempty strings.")
    if len(value) != len(set(value)):
        raise ValueError(f"Duplicate values in {label}.")
    return value


def text_parts(value):
    if isinstance(value, str):
        try:
            decoded = json.loads(value)
        except (json.JSONDecodeError, ValueError):
            return [value]
        if isinstance(decoded, (dict, list)):
            return text_parts(decoded)
        return [value]
    if isinstance(value, dict):
        result = []
        for nested in value.values():
            result.extend(text_parts(nested))
        return result
    if isinstance(value, list):
        result = []
        for nested in value:
            result.extend(text_parts(nested))
        return result
    return []


def normalized(text):
    return " ".join(text.split())


def production_path(path):
    segments = path.lower().split("/")
    return (
        not any(segment in ["test", "tests", "__tests__", "docs", ".agents", ".claude"] for segment in segments)
        and not path.lower().endswith((".md", ".txt"))
    )


data = _items[0]["json"]
config = data["run_config"]
raw = data.get("output")
result = json.loads(raw) if isinstance(raw, str) else raw
if not isinstance(result, dict) or not isinstance(result.get("features"), list):
    raise ValueError("Formatter did not return a features array.")

features = result["features"]
if len(features) > config["max_features"]:
    raise ValueError("Proposal count exceeds configured scope.")
if not features:
    return [{"json": {
        "feature_key": config["target_feature_keys"][0],
        "display_name_fa": config.get("target_feature", {}).get("display_name_fa", ""),
        "proposal_data": json.dumps({"target_feature": config.get("target_feature")}, ensure_ascii=False),
        "review_status": "no_supported_feature",
        "source_ref": config["source_ref"],
        "source_commit": data.get("source_commit", ""),
        "run_id": str(data["run_id"])
    }}]

commit = data.get("source_commit", "")
if not isinstance(commit, str) or len(commit) != 40 or any(
    char not in "0123456789abcdef" for char in commit.lower()
):
    raise ValueError("A pinned Git commit is required.")

read_files = {}
for step in data.get("read_steps", []):
    action = step.get("action", {})
    if action.get("tool") != "read_backend_file1":
        continue
    arguments = action.get("toolInput", {})
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except json.JSONDecodeError:
            continue
    if not isinstance(arguments, dict):
        continue
    path = arguments.get("file_path")
    if not isinstance(path, str) or not path:
        continue
    contents = text_parts(step.get("observation"))
    if contents:
        read_files.setdefault(path, []).extend(normalized(part) for part in contents)

if not read_files:
    raise ValueError("No source-read trace available; proposals cannot be verified.")


def check_evidence(evidence, label, require_production=False):
    if not isinstance(evidence, list) or not evidence:
        raise ValueError(f"Missing evidence: {label}.")
    has_production = False
    for citation in evidence:
        if not isinstance(citation, dict) or citation.get("repository") != "backend":
            raise ValueError(f"Invalid repository evidence: {label}.")
        path = citation.get("path")
        excerpt = citation.get("excerpt")
        if not isinstance(path, str) or path not in read_files:
            raise ValueError(f"Evidence path was not read in this run: {path}.")
        if not isinstance(excerpt, str) or not excerpt.strip():
            raise ValueError(f"Missing source excerpt: {label}.")
        if not any(normalized(excerpt) in content for content in read_files[path]):
            raise ValueError(f"Source excerpt does not match the read file: {path}.")
        has_production = has_production or production_path(path)
    if require_production and not has_production:
        raise ValueError(f"Production source evidence is required: {label}.")


rows = []
seen = set()
for feature in features:
    key = feature.get("feature_key")
    if (
        not isinstance(key, str) or not key
        or key[0] not in "abcdefghijklmnopqrstuvwxyz"
        or any(char not in "abcdefghijklmnopqrstuvwxyz0123456789_" for char in key)
        or key in seen
    ):
        raise ValueError("Invalid or duplicate feature key.")
    seen.add(key)

    if config["mode"] in ["review_existing", "analyze_new"]:
        if key not in config["target_feature_keys"]:
            raise ValueError("Proposal is outside the configured target features.")
    elif config["mode"] == "discover_new":
        if key in config["existing_feature_keys"]:
            raise ValueError("Discovery returned an existing feature.")
    else:
        raise ValueError("Unsupported catalog mode.")

    check_evidence(feature.get("evidence"), key, True)
    identifiers = set()
    for identifier in feature.get("required_identifiers", []):
        name = identifier.get("name")
        if not isinstance(name, str) or not name.strip() or name in identifiers:
            raise ValueError("Invalid or duplicate identifier definition.")
        identifiers.add(name)
        check_evidence(identifier.get("evidence"), name, True)

    intake = feature.get("intake_rules")
    if not isinstance(intake, dict) or isinstance(intake.get("version"), bool) or intake.get("version") != 1:
        raise ValueError("Unsupported intake rule version.")
    rules = intake.get("rules")
    reviews = feature.get("intake_rule_reviews")
    if not isinstance(rules, list) or not isinstance(reviews, list):
        raise ValueError("Rules and reviews must be arrays.")
    if not rules and not feature.get("uncertainties"):
        raise ValueError("Explain why no intake rules could be proposed.")

    review_map = {}
    for review in reviews:
        selector = (review.get("scenario"), review.get("request_state"))
        if selector in review_map:
            raise ValueError("Duplicate rule review.")
        if not isinstance(review.get("rationale"), str) or not review["rationale"].strip():
            raise ValueError("A rule review needs a rationale.")
        review_map[selector] = review

    selectors = set()
    for rule in rules:
        selector = (rule.get("scenario"), rule.get("request_state"))
        if selector[0] not in SCENARIOS or selector[1] not in STATES or selector in selectors:
            raise ValueError("Invalid or duplicate scenario rule.")
        selectors.add(selector)

        fields = strings(rule.get("required_case_fields"), "required_case_fields")
        required = strings(rule.get("required_identifiers"), "required_identifiers")
        unavailable = strings(rule.get("unavailable_identifiers"), "unavailable_identifiers")
        if not set(fields).issubset(ALLOWED_FIELDS):
            raise ValueError("Rule references an unsupported case field.")
        if not set(required + unavailable).issubset(identifiers):
            raise ValueError("Rule references an undefined catalog identifier.")
        if set(required) & set(unavailable):
            raise ValueError("An identifier cannot be both required and unavailable.")
        if not fields and not required:
            raise ValueError("A rule must contain meaningful intake requirements.")

        questions = rule.get("questions")
        if not isinstance(questions, dict) or any(
            field not in fields + required
            or not isinstance(question, str) or not question.strip()
            for field, question in questions.items()
        ):
            raise ValueError("Invalid catalog questions.")

        review = review_map.get(selector)
        if review is None:
            raise ValueError("Every rule needs a matching review.")
        expected = (
            {("required_case_field", field) for field in fields}
            | {("required_identifier", name) for name in required}
            | {("unavailable_identifier", name) for name in unavailable}
        )
        reviewed = set()
        for requirement in review.get("requirements", []):
            identity = (requirement.get("kind"), requirement.get("field"))
            if identity not in expected or identity in reviewed:
                raise ValueError("Unexpected or duplicate requirement rationale.")
            reviewed.add(identity)
            if requirement.get("basis") not in ["source_constraint", "investigation_policy"]:
                raise ValueError("Requirement needs an explicit source/policy basis.")
            if not isinstance(requirement.get("reason"), str) or not requirement["reason"].strip():
                raise ValueError("Requirement needs a reason.")
            check_evidence(requirement.get("evidence"), str(identity), True)
        if reviewed != expected:
            raise ValueError("Every proposed requirement needs evidence and a rationale.")

    if set(review_map) != selectors:
        raise ValueError("Reviews do not match proposed rules.")

    rows.append({"json": {
        "feature_key": key,
        "display_name_fa": feature["display_name_fa"],
        "proposal_data": json.dumps(feature, ensure_ascii=False),
        "review_status": "pending_review",
        "source_ref": config["source_ref"],
        "source_commit": commit,
        "run_id": str(data["run_id"])
    }})

return rows

