const scope = $('Prepare Catalog Scope').first().json;
const features = $input.first().json.output?.features;
if (!Array.isArray(features) || features.length === 0) {
  throw new Error('Inventory returned no features.');
}

// Skip features that already have a proposal, so an interrupted run resumes; failed ones are retried.
const done = new Set(
  $('Get Existing Proposals').all()
    .map(item => item.json)
    .filter(row => row.feature_key && row.review_status !== 'analysis_failed')
    .map(row => row.feature_key)
);

const seen = new Set();
const batches = [];
for (const feature of features) {
  const key = feature.feature_key;
  if (typeof key !== 'string' || !/^[a-z][a-z0-9_]*$/.test(key)) {
    throw new Error(`Invalid feature_key: ${key}`);
  }
  if (seen.has(key) || done.has(key)) continue;
  seen.add(key);
  batches.push({ json: {
    mode: scope.existing_feature_keys.includes(key) ? 'review_existing' : 'analyze_new',
    max_features: 1,
    tool_call_budget: scope.tool_call_budget,
    target_feature_keys: [key],
    target_feature: feature,
    existing_catalog: scope.existing_catalog.filter(entry => entry.feature_key === key),
    existing_feature_keys: scope.existing_feature_keys,
    source_ref: scope.source_ref,
  } });
}
return batches;
